package com.hbm.satellite.cargo;
import com.hbm.satellite.SatelliteCargo;import java.util.List;import net.minecraft.core.registries.Registries;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.fml.event.lifecycle.FMLCommonSetupEvent;import net.neoforged.neoforge.registries.*;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;import net.neoforged.neoforge.network.IContainerFactory;
public final class SatelliteCargoContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<EntityType<?>> MOBS=DeferredRegister.create(Registries.ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");
 public static final DeferredBlock<SatelliteDockBlock> BLOCK=BLOCKS.register("sat_dock",SatelliteDockBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem("sat_dock",BLOCK);public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<SatelliteDockBlockEntity>> ENTITY=ENTITIES.register("sat_dock",()->BlockEntityType.Builder.of(SatelliteDockBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<SatelliteDockPort>> PORT=ENTITIES.register("sat_dock_port",()->BlockEntityType.Builder.of(SatelliteDockPort::new,BLOCK.get()).build(null));public static final DeferredHolder<MenuType<?>,MenuType<SatelliteDockMenu>> MENU=MENUS.register("sat_dock",()->new MenuType<>((IContainerFactory<SatelliteDockMenu>)SatelliteDockMenu::new,FeatureFlags.DEFAULT_FLAGS));
 public static final DeferredHolder<EntityType<?>,EntityType<SatellitePod>> POD=MOBS.register("entity_miner_lander",()->EntityType.Builder.<SatellitePod>of(SatellitePod::new,MobCategory.MISC).sized(.95F,5.25F).fireImmune().clientTrackingRange(64).updateInterval(1).build("hbm:entity_miner_lander"));
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MOBS.register(bus);MENUS.register(bus);bus.addListener(SatelliteCargoContent::capabilities);bus.addListener((FMLCommonSetupEvent event)->event.enqueueWork(()->SatelliteCargo.transport=(level,x,y,z,cargo)->{if(!level.hasChunk(x>>4,z>>4))return false;var pod=new SatellitePod(level).setup(y,cargo);pod.setPos(x+.5,300,z+.5);return level.addFreshEntity(pod);}));}
 private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(be,side)->side==null?new InvWrapper(be):new SidedInvWrapper(be,side));event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,PORT.get(),(be,side)->side==null?new InvWrapper(be):new SidedInvWrapper(be,side));}public static List<ItemStack> creativeStacks(String tab){return tab.equals("missile")?List.of(new ItemStack(ITEM.get())):List.of();}private SatelliteCargoContent(){}
}
